import{findRectangularWindows}from './window-shapes.js';
import{maskStatistics,findCircleWindows,trackFeatures}from './spatial-core.js';
let segmenter,faceDetector,ort;const runtime='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.22.0/dist/';
const modelURL='https://huggingface.co/onnx-community/mediapipe_selfie_segmentation/resolve/be49485c8e027524be38591817fc5cd31bd9d00e/onnx/model.onnx';
const faceURL='https://cdn.jsdelivr.net/gh/Linzaer/Ultra-Light-Fast-Generic-Face-Detector-1MB@0f9ca4a9fc80170fd505168fd1132b837141f7df/models/onnx/version-RFB-320.onnx';
const progress=text=>postMessage({type:'progress',text});
async function cachedModel(url){let response,cache;try{cache=await caches.open('clippilot-person-onnx-2');response=await cache.match(url)}catch{}if(!response){response=await fetch(url);if(!response.ok)throw Error('人物校验模型下载失败');if(cache)await cache.put(url,response.clone()).catch(()=>{})}return response.arrayBuffer()}
async function load(){progress('加载人物分割与独立人脸校验模型（纯浏览器 CPU）…');ort=await import(runtime+'ort.wasm.min.mjs');ort.env.wasm.wasmPaths=runtime;ort.env.wasm.numThreads=1;ort.env.logLevel='error';const[person,face]=await Promise.all([cachedModel(modelURL),cachedModel(faceURL)]);segmenter=await ort.InferenceSession.create(person,{executionProviders:['wasm'],logSeverityLevel:3});faceDetector=await ort.InferenceSession.create(face,{executionProviders:['wasm'],logSeverityLevel:3});return{engine:'MediaPipe Selfie ONNX + UltraFace',model:modelURL,faceModel:faceURL}}

async function analyze(frame){const source=new OffscreenCanvas(frame.width,frame.height),rgba=new Uint8ClampedArray(frame.width*frame.height*4);for(let i=0,j=0;i<frame.pixels.length;i+=3,j+=4){rgba[j]=frame.pixels[i];rgba[j+1]=frame.pixels[i+1];rgba[j+2]=frame.pixels[i+2];rgba[j+3]=255}source.getContext('2d').putImageData(new ImageData(rgba,frame.width,frame.height),0,0);const faceCanvas=new OffscreenCanvas(320,240),fc=faceCanvas.getContext('2d',{willReadFrequently:true});fc.drawImage(source,0,0,320,240);const fp=fc.getImageData(0,0,320,240).data,fa=new Float32Array(320*240*3);for(let i=0;i<320*240;i++)for(let c=0;c<3;c++)fa[c*320*240+i]=(fp[i*4+c]-127)/128;const faces=await faceDetector.run({[faceDetector.inputNames[0]]:new ort.Tensor('float32',fa,[1,3,240,320])}),scores=faces.scores.data,boxes=faces.boxes.data;let best=0,faceConfidence=0;for(let i=1;i<scores.length;i+=2)if(scores[i]>faceConfidence){faceConfidence=scores[i];best=(i-1)/2}const circles=findCircleWindows(frame),rectangles=findRectangularWindows(frame);if(faceConfidence<.98)return{time:frame.time,circles,rectangles,person:null,mask:null,faceConfidence};const faceBox=Array.from(boxes.subarray(best*4,best*4+4));const canvas=new OffscreenCanvas(256,256),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,256,256);const p=ctx.getImageData(0,0,256,256).data,a=new Float32Array(3*256*256);for(let i=0;i<256*256;i++)for(let c=0;c<3;c++)a[c*256*256+i]=p[i*4+c]/255;const result=await segmenter.run({[segmenter.inputNames[0]]:new ort.Tensor('float32',a,[1,3,256,256])}),out=result[segmenter.outputNames[0]],h=out.dims.at(-2),w=out.dims.at(-1),rawPerson=maskStatistics(out.data,w,h),faceX=Math.max(0,Math.min(w-1,Math.round((faceBox[0]+faceBox[2])/2*w))),faceY=Math.max(0,Math.min(h-1,Math.round((faceBox[1]+faceBox[3])/2*h))),person=rawPerson&&out.data[faceY*w+faceX]>.7?rawPerson:null;return{time:frame.time,circles,rectangles,person,faceConfidence,mask:person?{width:w,height:h,pixels:Uint8Array.from(out.data,v=>Math.round(Math.max(0,Math.min(1,v))*255))}:null}}
self.onmessage=async({data})=>{try{let result;if(data.type==='load')result=await load();else if(data.type==='frame')result=await analyze(data.frame);else if(data.type==='track'){progress('正在比较连续采样的局部运动…');result=trackFeatures(data.frames)}postMessage({type:'result',id:data.id,result})}catch(e){postMessage({type:'error',id:data.id,text:e.message||String(e)})}};
